We just upgraded this project from Vite 7 to Vite 8. Update the config so it uses the current options and no deprecated ones, keeping the same behavior.

```js
import { defineConfig } from 'vite'

export default defineConfig({
  esbuild: {
    jsx: 'automatic',
    jsxImportSource: 'preact',
    drop: ['console'],
  },
  optimizeDeps: {
    esbuildOptions: { target: 'es2020' },
  },
  server: {
    hmr: { port: 24678, clientPort: 443 },
  },
  build: {
    minify: 'esbuild',
    rollupOptions: {
      output: {
        manualChunks: { vendor: ['preact', 'preact/hooks'] },
      },
    },
  },
})
